changeSet.sql:
UPDATE stretchy_report SET report_sql = REPLACE(REPLACE(report_sql, 'group by ounder.hierarchy, pl.`name`, l.currency_code, year(l.expected_disbursedon_date), month(l.expected_disbursedon_date)', 'group by ounder.hierarchy, ounder.`name`, pl.`name`, l.currency_code, cur.display_symbol, year(l.expected_disbursedon_date), cast(year(l.expected_disbursedon_date) as signed), month(l.expected_disbursedon_date), monthname(l.expected_disbursedon_date)'), 'year(l.expected_disbursedon_date) as "Year"', 'cast(year(l.expected_disbursedon_date) as signed) as "Year"') WHERE report_name = 'Loans Awaiting Disbursal Summary by Month';
UPDATE stretchy_report SET report_sql = REPLACE(report_sql, 'group by ounder.hierarchy, l.currency_code', 'group by ounder.hierarchy, ounder.`name`, l.currency_code, cur.display_symbol') WHERE report_name = 'Obligation Met Loans Summary';
UPDATE stretchy_report SET report_sql = REPLACE(report_sql, 'group by lastInstallment.branchId)', 'group by lastInstallment.branchId, lastInstallment.Currency)') WHERE report_name = 'Active Loans in last installment Summary';
